document.addEventListener("DOMContentLoaded",function(){const tabsContainer=document.getElementById("tabs-container");if(!tabsContainer)return;let currentMetric="payments";const formatMetric=val=>{if(currentMetric==="usd"){if(Math.abs(val)<1)return"$0";return"$"+d3.format(".2s")(val).replace("G","B")}else{return d3.format(",")(val)}};const formatFullVal=val=>{if(currentMetric==="usd"){return"$"+d3.format(",.2f")(val)}else{return d3.format(",")(val)}};const colorPalette=["#2ec7c9","#b6a2de","#5ab1ef","#ffb980","#d87a80","#8d98b3","#e5cf0d","#97b552","#95706d","#dc69aa","#07a2a4","#9a7fd1","#588dd5","#f5994e","#c05050","#59678c","#c9ab00","#76933c","#bc65a6"];function getStableColor(name){if(!name)return"#5470c6";let hash=0;for(let i=0;i<name.length;i++){hash=name.charCodeAt(i)+((hash<<5)-hash)}const index=Math.abs(hash)%colorPalette.length;return colorPalette[index]}let ndx=crossfilter([]);const isFr=document.documentElement.lang&&document.documentElement.lang.startsWith("fr");const t=(en,fr)=>isFr?fr:en;const dateDimension=ndx.dimension(d=>d.date);const countryDimension=ndx.dimension(d=>d.country_slug);const primaryDimFilter=d=>d.dimension_type==="status";const moveDays=dateDimension.group(d3.timeDay);const moveMonths=dateDimension.group(d3.timeMonth);const reconciledMonthGroup=moveMonths.reduce((p,v)=>{if(primaryDimFilter(v)&&v.dimension_value){const key=String(v.dimension_value).toUpperCase();if(key.includes("RECONCILED")||key.includes("PAID")){p.payments+=v.payment_count;p.usd+=+v.total_usd}}return p},(p,v)=>{if(primaryDimFilter(v)&&v.dimension_value){const key=String(v.dimension_value).toUpperCase();if(key.includes("RECONCILED")||key.includes("PAID")){p.payments-=v.payment_count;p.usd-=+v.total_usd}}return p},()=>({payments:0,usd:0}));const openedMonthGroup=moveMonths.reduce((p,v)=>{if(primaryDimFilter(v)&&v.dimension_value){const key=String(v.dimension_value).toUpperCase();if(key.includes("OPEN")||key.includes("PENDING")){p.payments+=v.payment_count;p.usd+=+v.total_usd}}return p},(p,v)=>{if(primaryDimFilter(v)&&v.dimension_value){const key=String(v.dimension_value).toUpperCase();if(key.includes("OPEN")||key.includes("PENDING")){p.payments-=v.payment_count;p.usd-=+v.total_usd}}return p},()=>({payments:0,usd:0}));const countryStatusGroup=countryDimension.group().reduce((p,v)=>{if(primaryDimFilter(v)&&v.dimension_value){const key=String(v.dimension_value).toUpperCase();const isReconciled=key.includes("RECONCILED")||key.includes("PAID");const isOpened=key.includes("OPEN")||key.includes("PENDING");if(isReconciled){p.reconciled_payments+=v.payment_count;p.reconciled_usd+=+v.total_usd}else if(isOpened){p.opened_payments+=v.payment_count;p.opened_usd+=+v.total_usd}}return p},(p,v)=>{if(primaryDimFilter(v)&&v.dimension_value){const key=String(v.dimension_value).toUpperCase();const isReconciled=key.includes("RECONCILED")||key.includes("PAID");const isOpened=key.includes("OPEN")||key.includes("PENDING");if(isReconciled){p.reconciled_payments-=v.payment_count;p.reconciled_usd-=+v.total_usd}else if(isOpened){p.opened_payments-=v.payment_count;p.opened_usd-=+v.total_usd}}return p},()=>({reconciled_payments:0,reconciled_usd:0,opened_payments:0,opened_usd:0}));const selectedCountries=new Set;const timelineChart=echarts.init(document.getElementById("time-focus-chart"),"macarons");const countryChart=echarts.init(document.getElementById("status-country-chart"),"macarons");const completionGauge=echarts.init(document.getElementById("completion-gauge"),"macarons");window.addEventListener("resize",function(){timelineChart.resize();countryChart.resize();completionGauge.resize()});function updateTotals(){const totalReconciled=ndx.groupAll().reduceSum(d=>{if(!primaryDimFilter(d)||!d.dimension_value)return 0;const key=String(d.dimension_value).toUpperCase();const match=key.includes("RECONCILED")||key.includes("PAID");return match?currentMetric==="usd"?+d.total_usd:d.payment_count:0}).value();const totalOpened=ndx.groupAll().reduceSum(d=>{if(!primaryDimFilter(d)||!d.dimension_value)return 0;const key=String(d.dimension_value).toUpperCase();const match=key.includes("OPEN")||key.includes("PENDING");return match?currentMetric==="usd"?+d.total_usd:d.payment_count:0}).value();const total=totalReconciled+totalOpened;const reconciledPct=total>0?(totalReconciled/total*100).toFixed(1):0;const openedPct=total>0?(totalOpened/total*100).toFixed(1):0;const completionRate=total>0?totalReconciled/total*100:0;const outOfReconciled=t(`${reconciledPct}% out of ${formatFullVal(total)} total`,`${reconciledPct}% sur ${formatFullVal(total)} au total`);document.getElementById("total-reconciled").textContent=`${formatFullVal(totalReconciled)} (${outOfReconciled})`;const outOfOpened=t(`${openedPct}% out of ${formatFullVal(total)} total`,`${openedPct}% sur ${formatFullVal(total)} au total`);document.getElementById("total-opened").textContent=`${formatFullVal(totalOpened)} (${outOfOpened})`;document.getElementById("completion-rate-text").textContent=`${completionRate.toFixed(1)}%`;completionGauge.setOption({series:[{type:"gauge",startAngle:180,endAngle:0,center:["50%","75%"],radius:"95%",min:0,max:100,splitNumber:2,axisLine:{lineStyle:{width:5,color:[[.3,"#d87a80"],[.7,"#ffb980"],[1,"#2ec7c9"]]}},pointer:{icon:"path://M12.8,29.5C13,29.5,13,29.5,13,29.5c0-0.4-0.3-0.7-0.7-0.7c-0.4,0-0.7,0.3-0.7,0.7C11.6,29.5,11.7,29.5,12.8,29.5z",width:2.5,length:"60%",offsetCenter:[0,2]},axisTick:{show:false},splitLine:{show:false},axisLabel:{show:false},title:{show:false},detail:{show:false},data:[{value:completionRate.toFixed(1)}]}]},{notMerge:true})}function updateAll(filterSource=null){updateTotals();const unitName=currentMetric==="usd"?"USD":t("payments","paiements");const reconciledData=reconciledMonthGroup.all().filter(d=>d.key!==null).map(d=>[d.key.getTime(),d.value[currentMetric]]);const openedData=openedMonthGroup.all().filter(d=>d.key!==null).map(d=>[d.key.getTime(),d.value[currentMetric]]);const timelineOption={tooltip:{trigger:"axis",axisPointer:{type:"shadow"},formatter:function(params){const date=new Date(params[0].value[0]);const formattedDate=d3.timeFormat("%B %Y")(date);let tooltipHtml=`${formattedDate}<br/>`;params.forEach(p=>{tooltipHtml+=`${p.marker} ${p.seriesName}: <b>${formatFullVal(p.value[1])}</b> ${unitName}<br/>`});return tooltipHtml}},legend:{data:[t("Reconciled","Rapproché"),t("Still Opened","En cours")],bottom:0,icon:"roundRect"},grid:{top:20,bottom:80,left:70,right:30},xAxis:{type:"time",axisLabel:{color:"#64748b"}},yAxis:{type:"value",axisLabel:{formatter:val=>formatMetric(val),color:"#64748b"},splitLine:{lineStyle:{type:"dashed",color:"#f1f5f9"}}},series:[{name:t("Reconciled","Rapproché"),type:"bar",stack:"total",color:"#97b552",barMaxWidth:35,data:reconciledData},{name:t("Still Opened","En cours"),type:"bar",stack:"total",color:"#5ab1ef",barMaxWidth:35,data:openedData}]};if(filterSource!=="timeline"){timelineOption.dataZoom=[{type:"inside",start:0,end:100},{show:true,type:"slider",start:0,end:100,bottom:30,textStyle:{color:"#64748b"}}];timelineChart.setOption(timelineOption,{notMerge:true})}else{timelineChart.setOption(timelineOption)}const countryData=countryStatusGroup.all().map(d=>{const reconciled=currentMetric==="usd"?d.value.reconciled_usd:d.value.reconciled_payments;const opened=currentMetric==="usd"?d.value.opened_usd:d.value.opened_payments;return{key:d.key,reconciled:reconciled,opened:opened,total:reconciled+opened}}).filter(d=>d.key!==""&&d.key!==null&&d.total>0).sort((a,b)=>b.total-a.total).slice(0,15);const hasAnyCountrySelection=selectedCountries.size>0;const countrySeriesDataReconciled=countryData.map(d=>{const isSelected=selectedCountries.has(d.key);const opacity=isSelected?1:hasAnyCountrySelection?.35:1;return{value:d.reconciled,itemStyle:{color:"#97b552",opacity:opacity}}});const countrySeriesDataOpened=countryData.map(d=>{const isSelected=selectedCountries.has(d.key);const opacity=isSelected?1:hasAnyCountrySelection?.35:1;return{value:d.opened,itemStyle:{color:"#5ab1ef",opacity:opacity}}});countryChart.setOption({tooltip:{trigger:"axis",axisPointer:{type:"shadow"},formatter:function(params){let tooltipHtml=`${params[0].name}<br/>`;params.forEach(p=>{tooltipHtml+=`${p.marker} ${p.seriesName}: <b>${formatFullVal(p.value)}</b> ${unitName}<br/>`});return tooltipHtml}},legend:{data:[t("Reconciled","Rapproché"),t("Still Opened","En cours")],top:0,right:20},grid:{top:35,bottom:95,left:75,right:20},xAxis:{type:"category",data:countryData.map(d=>d.key),axisLabel:{rotate:30,interval:0,color:"#1f2937",fontWeight:500}},yAxis:{type:"value",axisLabel:{formatter:val=>formatMetric(val),color:"#64748b"},splitLine:{lineStyle:{color:"#f1f5f9"}}},series:[{name:t("Reconciled","Rapproché"),type:"bar",stack:"total",barMaxWidth:30,data:countrySeriesDataReconciled,itemStyle:{borderRadius:[0,0,0,0]}},{name:t("Still Opened","En cours"),type:"bar",stack:"total",barMaxWidth:30,data:countrySeriesDataOpened,itemStyle:{borderRadius:[4,4,0,0]}}]},{notMerge:true})}timelineChart.on("datazoom",function(params){const option=timelineChart.getOption();const startVal=option.dataZoom[0].startValue;const endVal=option.dataZoom[0].endValue;if(startVal!==undefined&&endVal!==undefined){const startDate=new Date(startVal);const endDate=new Date(endVal);dateDimension.filterRange([startDate,endDate]);updateAll("timeline")}});countryChart.on("click",function(params){const countryName=params.name;if(selectedCountries.has(countryName)){selectedCountries.delete(countryName)}else{selectedCountries.add(countryName)}if(selectedCountries.size===0){countryDimension.filterAll()}else{countryDimension.filterFunction(d=>selectedCountries.has(d))}updateAll()});const metricTabs=document.querySelectorAll(".metric-tab");metricTabs.forEach(btn=>{btn.addEventListener("click",function(){metricTabs.forEach(b=>{b.classList.remove("bg-white","shadow","text-blue-800","active-metric");b.classList.add("text-gray-600")});this.classList.add("bg-white","shadow","text-blue-800","active-metric");this.classList.remove("text-gray-600");currentMetric=this.dataset.metric;const reconciledTitle=document.getElementById("reconciled-card-title");const openedTitle=document.getElementById("opened-card-title");const timelineTitle=document.getElementById("timeline-title");const countryTitle=document.getElementById("country-chart-title");if(currentMetric==="usd"){if(reconciledTitle)reconciledTitle.textContent=t("Reconciled Amount (USD)","Montant rapproché (USD)");if(openedTitle)openedTitle.textContent=t("Still Opened Amount (USD)","Montant toujours ouvert (USD)");if(timelineTitle)timelineTitle.textContent=t("Reconciliation Timeline (USD)","Chronologie du rapprochement (USD)");if(countryTitle)countryTitle.textContent=t("Reconciliation Status by Country (USD)","État du rapprochement par pays (USD)")}else{if(reconciledTitle)reconciledTitle.textContent=t("Reconciled Payments","Paiements rapprochés");if(openedTitle)openedTitle.textContent=t("Still Opened Payments","Paiements toujours ouverts");if(timelineTitle)timelineTitle.textContent=t("Reconciliation Timeline","Chronologie du rapprochement");if(countryTitle)countryTitle.textContent=t("Reconciliation Status by Country","État du rapprochement par pays")}updateAll()})});async function loadData(year){try{const url=`${window.DASHBOARD_CONFIG.endpoint}?year=${year}&dashboard=${window.DASHBOARD_CONFIG.type}`;const response=await fetch(url,{credentials:"same-origin",headers:{Accept:"application/json","X-Requested-With":"XMLHttpRequest"}});if(!response.ok){if(response.status===403){console.error("Authentication required. Please log in.");return}throw new Error(`HTTP error! status: ${response.status}`)}const data=await response.json();const dateFormat=d3.timeParse("%Y-%m-%d");data.forEach(d=>{d.date=dateFormat(d.date);d.total_usd=+d.total_usd;d.payment_count=+d.payment_count});const now=new Date;now.setHours(23,59,59,999);const currentData=data.filter(d=>d.date<=now);selectedCountries.clear();countryDimension.filterAll();dateDimension.filterAll();ndx.remove();ndx.add(currentData);updateAll()}catch(error){console.error("Error loading completion data:",error)}}tabsContainer.querySelectorAll(".year-tab").forEach(btn=>{btn.addEventListener("click",function(){tabsContainer.querySelectorAll(".year-tab").forEach(b=>b.classList.remove("bg-white","shadow","text-blue-600","active-tab"));this.classList.add("bg-white","shadow","text-blue-600","active-tab");loadData(this.dataset.year)})});const firstYear=tabsContainer.querySelector(".active-tab")?.dataset.year;if(firstYear){loadData(firstYear)}});
